Below is a complete `benchmark.py` that meets all requirements. It uses **only Python stdlib**, supports **both Chat Completions and Responses APIs**, streams SSE, measures **TTFT**, handles errors gracefully, supports concurrency, and writes results to JSON.

```python
#!/usr/bin/env python3
import argparse
import concurrent.futures
import datetime
import json
import os
import socket
import sys
import time
import uuid
import urllib.request
import urllib.error
from functools import partial

PROMPT = "Reply with exactly one sentence about the color blue."


def _ms(seconds: float) -> float:
    return round(seconds * 1000.0, 3)


def load_models(config_path: str):
    try:
        with open(config_path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except FileNotFoundError:
        raise ValueError(f"Config file not found: {config_path}")
    except json.JSONDecodeError as e:
        raise ValueError(f"Config JSON parse error: {e}")

    models = data.get("models")
    if not isinstance(models, list):
        raise ValueError("Config JSON must contain a 'models' list")
    return models


def parse_sse_stream(response, api_type: str, t_start: float):
    full_text = ""
    first_token = None
    ttft_ms = None

    for raw_line in response:
        if not raw_line:
            continue
        try:
            line = raw_line.decode("utf-8")
        except Exception:
            line = raw_line.decode("utf-8", errors="ignore")

        line = line.strip()
        if not line:
            continue
        if not line.startswith("data:"):
            continue

        data = line[len("data:"):].strip()
        if data == "[DONE]":
            break

        try:
            obj = json.loads(data)
        except json.JSONDecodeError as e:
            raise ValueError(f"JSON parse error: {e}")

        content = None
        if api_type == "chat_completions":
            choices = obj.get("choices")
            if isinstance(choices, list) and choices:
                delta = choices[0].get("delta") if isinstance(choices[0], dict) else None
                if isinstance(delta, dict):
                    content = delta.get("content")
        elif api_type == "responses":
            if obj.get("type") == "content_block_delta":
                delta = obj.get("delta")
                if isinstance(delta, dict):
                    content = delta.get("text")

        if content is not None and content != "":
            if ttft_ms is None:
                ttft_ms = _ms(time.perf_counter() - t_start)
                first_token = content
            full_text += content

    return full_text, first_token, ttft_ms


def benchmark_model(model: dict, prompt: str, timeout: float):
    model_id = model.get("id")
    api_type = model.get("api_type")

    result = {
        "model_id": model_id,
        "api_type": api_type,
        "status": "error",
        "ttft_ms": None,
        "total_ms": None,
        "first_token": None,
        "full_response": None,
        "error": None,
    }

    t_start = time.perf_counter()

    try:
        if not model_id:
            raise ValueError("Missing model id")
        if not api_type:
            raise ValueError("Missing api_type")
        base_url = model.get("base_url")
        if not base_url:
            raise ValueError("Missing base_url")
        api_key_env = model.get("api_key_env")
        if not api_key_env:
            raise ValueError("Missing api_key_env")
        api_key = os.environ.get(api_key_env)
        if not api_key:
            raise ValueError(f"API key env '{api_key_env}' not set")

        if api_type == "chat_completions":
            endpoint = "/v1/chat/completions"
            body = {
                "model": model_id,
                "messages": [{"role": "user", "content": prompt}],
                "stream": True,
            }
        elif api_type == "responses":
            endpoint = "/v1/responses"
            body = {
                "model": model_id,
                "input": prompt,
                "stream": True,
            }
        else:
            raise ValueError(f"Unknown api_type: {api_type}")

        if model.get("temperature") is not None:
            body["temperature"] = model.get("temperature")
        if model.get("max_tokens") is not None:
            body["max_tokens"] = model.get("max_tokens")

        url = base_url.rstrip("/") + endpoint
        data = json.dumps(body).encode("utf-8")

        headers = {
            "Content-Type": "application/json",
            "Accept": "text/event-stream",
            "Authorization": f"Bearer {api_key}",
        }

        req = urllib.request.Request(url, data=data, headers=headers, method="POST")

        with urllib.request.urlopen(req, timeout=timeout) as resp:
            full_response, first_token, ttft_ms = parse_sse_stream(resp, api_type, t_start)

        total_ms = _ms(time.perf_counter() - t_start)

        result.update({
            "status": "ok",
            "ttft_ms": ttft_ms,
            "total_ms": total_ms,
            "first_token": first_token,
            "full_response": full_response,
            "error": None
        })

    except urllib.error.HTTPError as e:
        total_ms = _ms(time.perf_counter() - t_start)
        msg = f"HTTP error {e.code}: {e.reason}"
        try:
            body = e.read().decode("utf-8", errors="ignore")
            if body:
                msg += f" - {body}"
        except Exception:
            pass
        result.update({
            "status": "error",
            "ttft_ms": None,
            "total_ms": total_ms,
            "first_token": None,
            "full_response": None,
            "error": msg
        })

    except urllib.error.URLError as e:
        total_ms = _ms(time.perf_counter() - t_start)
        if isinstance(e.reason, socket.timeout):
            msg = f"Connection timeout after {int(timeout * 1000)}ms"
        else:
            msg = f"Connection error: {e.reason}"
        result.update({
            "status": "error",
            "ttft_ms": None,
            "total_ms": total_ms,
            "first_token": None,
            "full_response": None,
            "error": msg
        })

    except socket.timeout:
        total_ms = _ms(time.perf_counter() - t_start)
        msg = f"Connection timeout after {int(timeout * 1000)}ms"
        result.update({
            "status": "error",
            "ttft_ms": None,
            "total_ms": total_ms,
            "first_token": None,
            "full_response": None,
            "error": msg
        })

    except Exception as e:
        total_ms = _ms(time.perf_counter() - t_start)
        result.update({
            "status": "error",
            "ttft_ms": None,
            "total_ms": total_ms,
            "first_token": None,
            "full_response": None,
            "error": str(e)
        })

    return result


def run_benchmarks(models, prompt, timeout, workers):
    if workers <= 1:
        return [benchmark_model(m, prompt, timeout) for m in models]

    func = partial(benchmark_model, prompt=prompt, timeout=timeout)
    with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as executor:
        return list(executor.map(func, models))


def compute_summary(results):
    total = len(results)
    ok_results = [r for r in results if r.get("status") == "ok"]
    errors = total - len(ok_results)

    ttfts = [r["ttft_ms"] for r in ok_results if r.get("ttft_ms") is not None]
    avg_ttft_ms = sum(ttfts) / len(ttfts) if ttfts else None

    fastest_model = None
    slowest_model = None
    if ttfts:
        ok_with_ttft = [r for r in ok_results if r.get("ttft_ms") is not None]
        fastest_model = min(ok_with_ttft, key=lambda r: r["ttft_ms"])["model_id"]
        slowest_model = max(ok_with_ttft, key=lambda r: r["ttft_ms"])["model_id"]

    return {
        "total": total,
        "ok": len(ok_results),
        "errors": errors,
        "avg_ttft_ms": avg_ttft_ms,
        "fastest_model": fastest_model,
        "slowest_model": slowest_model,
    }


def main():
    parser = argparse.ArgumentParser(description="Multi-API LLM benchmark harness with TTFT measurement")
    parser.add_argument("--config", required=True, help="Path to model config JSON")
    parser.add_argument("--output", default="benchmark_results.json", help="Output JSON file")
    parser.add_argument("--timeout", type=float, default=30.0, help="Per-model timeout in seconds")
    parser.add_argument("--workers", type=int, default=1, help="Number of parallel workers")

    args = parser.parse_args()

    try:
        models = load_models(args.config)
    except ValueError as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

    results = run_benchmarks(models, PROMPT, args.timeout, args.workers)
    summary = compute_summary(results)

    output = {
        "run_id": str(uuid.uuid4()),
        "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        "prompt": PROMPT,
        "results": results,
        "summary": summary,
    }

    with open(args.output, "w", encoding="utf-8") as f:
        json.dump(output, f, indent=2)

    print(f"Saved results to {args.output}")


if __name__ == "__main__":
    main()
```

### Usage
```bash
python benchmark.py --config models.json --output results.json --timeout 10 --workers 4
```

This script fully complies with the given requirements: dual API support, SSE parsing, TTFT measurement, stdlib-only HTTP, robust error handling, and JSON output summary.
